// runOnceForAllItems. No $env here (Code nodes run in the task runner and don't
// see the deployment env). Paste your real profile into PROFILE below.
const res = $input.first().json;
const entries = Array.isArray(res.entries) ? res.entries : [];

const PROFILE = "You are a feed-triage assistant. Score each article 0-10 on how much it advances the reader's goals, then put it in one bucket.

READER  (replace this block with your real profile in this node; keep it out of the public repo)
Interested in applied AI / LLM engineering, cloud and object storage, Kubernetes and inference infrastructure, and self-hosting. Favour hands-on engineering depth and things worth writing about; discount news, funding and product announcements.

SCORE 0-10 ON GOAL LEVERAGE, NOT GENERAL INTEREST
9-10  reproduce-and-write-up depth, primary-source case studies, strong signal for the target field.
7-8   strongly relevant engineering patterns, techniques on the learning path, or a clear angle worth writing about.
5-6   tangentially useful: general platform/SRE/cost content, a technique that could become a writeup.
2-4   generic tech news, announcements with no engineering substance.
0-1   noise: unrelated, clickbait, marketing.

BUCKETS (pick one): career | applied-ai | infra | storage | homelab | noise

OUTPUT  Return ONLY a JSON object, no prose, no code fence:
{"score": <int 0-10>, "bucket": "<one bucket>", "why": "<=25 words>", "publish_angle": "<a post title the reader could write, or empty string>"}";

return entries.map((e) => {
  const html = e.content || e.summary || '';
  const text = String(html).replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 1400);
  const feed = (e.feed && e.feed.title) || '';
  const category = (e.feed && e.feed.category && e.feed.category.title) || '';
  const userMsg = 'TITLE: ' + e.title + '
FEED: ' + feed + '
CATEGORY: ' + category + '
URL: ' + e.url + '

EXCERPT:
' + (text || '(no excerpt)');
  return { json: { id: e.id, title: e.title, url: e.url, feed, category, sysPrompt: PROFILE, userMsg } };
});

// runOnceForEachItem. Pull the model verdict from this item, originals from Prep by index.
const orig = $('Prep entries').all()[$itemIndex].json;
let v = {};
try { v = JSON.parse(($json.message && $json.message.content) || '{}'); } catch (e) { v = {}; }

let score = Math.round(Number(v.score));
if (!Number.isFinite(score)) score = 0;
score = Math.max(0, Math.min(10, score));
const bucket = String(v.bucket || 'noise');
const why = String(v.why || '').slice(0, 240);
const angle = String(v.publish_angle || '').slice(0, 240);

let action = score >= 8 ? 'notify' : (score >= 6 ? 'star' : 'skip');

const now = $now.setZone('America/Chicago');
const hm = now.hour + now.minute / 60;
const quiet = (hm >= 22 || hm < 7.5);
const sd = $getWorkflowStaticData('global');
const today = now.toFormat('yyyy-LL-dd');
if (sd.capDate !== today) { sd.capDate = today; sd.capCount = 0; }
if (action === 'notify') {
  if (quiet || (sd.capCount || 0) >= 6) action = 'star';
  else sd.capCount = (sd.capCount || 0) + 1;
}

const emoji = ({ career: '🎯', storage: '🗄️', infra: '⚙️', 'applied-ai': '🤖', homelab: '🏠', noise: '·' })[bucket] || '•';
const gotifyPriority = score >= 9 ? 8 : 6;
const gotifyTitle = (emoji + ' [' + score + '] ' + (orig.feed || '')).slice(0, 120);
let gotifyMessage = '**' + orig.title + '**\n\n' + why;
if (angle) gotifyMessage += '\n\n✍️ Post angle: ' + angle;
gotifyMessage += '\n\n' + orig.url;
const karakeepNote = 'score ' + score + ' · ' + bucket + (why ? ' · ' + why : '') + (angle ? ' · angle: ' + angle : '');

return { json: { id: orig.id, url: orig.url, title: orig.title, feed: orig.feed, category: orig.category, score, bucket, why, publish_angle: angle, action, gotifyPriority, gotifyTitle, gotifyMessage, karakeepNote } };
